// Question bank for the Database Management Systems exam drill (NOVA IMS, 2026/2027).
// Unofficial: written from the course slides (Class 1 to Class 5). These are not real exam questions.
// M = multiple choice, T = true/false.
// a = index of the correct option in o (for T: true → 0, false → 1). The app shuffles M options.
// code (optional last argument) = block shown under the question in a monospaced font, line breaks kept.
// `backticks` inside any text render as inline code.

const CHAPTERS = {
  1: "ER Modelling Concepts",
  2: "From ER to Relational",
  3: "Modelling Cases: Library, Festival, TV Shows",
  4: "Timetables, Alternative Keys & Ride Hailing",
  5: "Relational Model & Normalization",
  6: "SQL Basics & DDL",
  7: "Reading Models: Private Clinic & Car-pooling",
  8: "Loading Data with SSMS",
};

const M = (c, q, o, a, e, code) => ({ c, q, o, a, e, code });
const T = (c, q, v, e, code) => ({ c, q, o: ["True", "False"], a: v ? 0 : 1, e, code, tf: true });

// Shared listings
const MOVIES_DDL = `create table Movies(
    ID int PRIMARY KEY,
    Title varchar(50),
    Year int,
    Director varchar(50),
    Duration int,
    CONSTRAINT AK_TITLE_YEAR
        UNIQUE (TITLE, YEAR));`;
const RATINGS_DDL = `CREATE TABLE Ratings(
    IDRATING int, IDCRITIC int, IDMOVIE int,
    STARS int, RATINGDATE date,
    PRIMARY KEY (IDRATING, IDCRITIC, IDMOVIE),
    FOREIGN KEY (IDCRITIC) REFERENCES CRITICS(ID),
    FOREIGN KEY (IDMOVIE) REFERENCES MOVIES(ID));`;
